    if (/^Numpad[0-9]$/.test(c)) return "Num" + c.slice(6);
    if (/^F\d{1,2}$/.test(c)) return c;
    const names = {
      Space: "Space",
      ArrowUp: "Up",
      ArrowDown: "Down",
      ArrowLeft: "Left",
      ArrowRight: "Right",
      Escape: "Esc",
    };
